// Preview renderers for the Astro website template (templates/website/components.md).
// Markup is ported from the live site (webagen.astrosynapse.ai/website), captured by rendering each
// spec example there, so classes and structure match. Styles: astro-base.css plus utilities
// generated by twlite.py from the classes in this file (keep class lists literal, or in tw`…`).
// Clicks: data-prompt = sends a query · data-href = navigates · data-action = static frontend action.
(function () {
  const R = (window.WEBAGEN_RENDERERS = window.WEBAGEN_RENDERERS || {});
  const tw = (s) => s.raw.join("");
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const img = (id, w, h) => (/^https?:\/\//.test(id) ? id : `https://images.unsplash.com/${id}?auto=format&fit=crop&crop=faces&w=${w}&h=${h}&q=70`);
  const pad = (n, w = 2) => String(n).padStart(w, "0");
  const words = (s) => String(s || "").trim().split(/\s+/);
  const list = (v) => (Array.isArray(v) ? v : typeof v === "string" && v ? v.split(",").map((x) => x.trim()).filter(Boolean) : []);
  const P = (s) => (s ? ` data-prompt="${esc(s)}"` : "");
  const H = (s) => (s ? ` data-href="${esc(s)}"` : "");

  /* Tabler icons (paths inline; the live site uses @tabler/icons-react) */
  const svg = (cls, paths) => `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="${cls}">${paths.map((d) => `<path d="${d}"/>`).join("")}</svg>`;
  const I = {
    right: (c) => svg(c, ["M5 12l14 0", "M13 18l6 -6", "M13 6l6 6"]),
    left: (c) => svg(c, ["M5 12l14 0", "M5 12l6 6", "M5 12l6 -6"]),
    down: (c) => svg(c, ["M12 5l0 14", "M18 13l-6 6", "M6 13l6 6"]),
    plus: (c) => svg(c, ["M12 5l0 14", "M5 12l14 0"]),
    linkedin: (c) => svg(c, ["M8 11v5", "M8 8v.01", "M12 16v-5", "M16 16v-3a2 2 0 1 0 -4 0", "M3 7a4 4 0 0 1 4 -4h10a4 4 0 0 1 4 4v10a4 4 0 0 1 -4 4h-10a4 4 0 0 1 -4 -4z"]),
    x: (c) => svg(c, ["M4 4l11.733 16h4.267l-11.733 -16z", "M4 20l6.768 -6.768m2.46 -2.46l6.772 -6.772"]),
    github: (c) => svg(c, ["M9 19c-4.3 1.4 -4.3 -2.5 -6 -3m12 5v-3.5c0 -1 .1 -1.4 -.5 -2c2.8 -.3 5.5 -1.4 5.5 -6a4.6 4.6 0 0 0 -1.3 -3.2a4.2 4.2 0 0 0 -.1 -3.2s-1.1 -.3 -3.5 1.3a12.3 12.3 0 0 0 -6.2 0c-2.4 -1.6 -3.5 -1.3 -3.5 -1.3a4.2 4.2 0 0 0 -.1 3.2a4.6 4.6 0 0 0 -1.3 3.2c0 4.6 2.7 5.7 5.5 6c-.6 .6 -.6 1.2 -.5 2v3.5"]),
  };

  /* Shared pieces (same classes as the live site) */
  const BTN = tw`inline-flex min-h-12 items-center justify-center gap-2 rounded-full border px-6 py-3 text-sm font-bold tracking-tight transition-all duration-200 ease-out border-transparent bg-foreground text-background hover:-translate-y-0.5 hover:astro-glow`;
  const button = (label, prompt, href, extra = "") => `<a href="#"${P(prompt)}${H(href)} class="${BTN} ${extra}"><span>${esc(label)}</span>${I.right("tabler-icon h-4 w-4")}</a>`;
  const dotBadge = (label) => `<div><span class="inline-flex items-center gap-2 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground"><span class="astro-dot-glow h-1.5 w-1.5 rounded-full bg-brand-cyan"></span>${esc(label)}</span></div>`;
  const PILL = tw`inline-flex min-h-6 max-w-full items-center break-words rounded-full border border-brand-cyan/20 px-2.5 py-0.5 font-plex-mono text-xs uppercase tracking-wider text-brand-cyan`;
  const pills = (ps) => (ps || []).length ? `<ul class="mt-3 flex flex-wrap gap-1.5">${ps.map((p) => `<li class="${PILL}">${esc(p.label ?? p)}</li>`).join("")}</ul>` : "";
  const STATUS = tw`inline-flex min-h-6 shrink-0 items-center whitespace-nowrap rounded-full border border-foreground/30 bg-background/50 px-2.5 py-0.5 font-plex-mono text-xs uppercase tracking-widest text-foreground`;
  const H3 = tw`text-foreground mb-4 mt-10 break-words font-inter text-2xl font-semibold tracking-tighter first:mt-0 md:text-3xl`;
  const PARA = tw`mb-5 max-w-2xl break-words text-base text-foreground/70 sm:text-lg md:text-xl`;
  const NUM_LI = tw`text-sm leading-relaxed relative break-words border-t border-foreground/10 py-3.5 pl-12 text-foreground/70`;
  const numbered = (items) => `<ol class="mb-6 flex w-full max-w-xl flex-col">${items.map((x, i) => `<li class="${NUM_LI}"><span class="absolute left-0 top-5 font-plex-mono text-xs tracking-widest text-brand-cyan">${pad(i + 1)}</span>${esc(x.text ?? x)}</li>`).join("")}</ol>`;
  const labeled = (items) => items.map((x) => `<p class="${PARA}"><span class="font-semibold text-foreground">${esc(x.label ?? x.title)}</span> ${esc(x.text)}</p>`).join("");
  // bullet lists: the spec allows them, the live site doesn't render them yet; drawn in the same style
  const bullets = (items) => `<ul class="mb-6 flex w-full max-w-xl flex-col">${items.map((x) => `<li class="${NUM_LI}"><span class="astro-dot-glow absolute left-1 top-5 h-1.5 w-1.5 rounded-full bg-brand-cyan"></span>${esc(x.text ?? x)}</li>`).join("")}</ul>`;
  const CONTAINER = tw`container px-4 sm:px-6 md:px-12`;
  const H2 = tw`text-foreground max-w-full break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:text-6xl`;
  const LEAD = tw`max-w-2xl break-words text-base leading-normal text-foreground/70 sm:text-lg md:text-xl`;
  const def = (name, render, extra = {}) => { R[name] = Object.assign({
    theme: "astro", rootClass: "astro-st-scope", bg: "hsl(var(--background))",
    htmlClass: (mode) => (mode === "dark" ? "dark " : "") + "font-satoshi",
    fonts: ["https://api.fontshare.com/v2/css?f[]=satoshi@400,500,700,900&display=swap", "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap"],
    render: (p) => `<section class="flex flex-col">${render(p || {})}</section>`,
  }, extra); };

  /* ---------- 1. Landing heading ---------- */
  def("astro-landing-heading", (p) => {
    const ctas = p.ctas || [];
    const marquee = list(p.marquee ?? p.marquees);
    const loop = marquee.length ? Array.from({ length: Math.max(2, Math.ceil(8 / marquee.length)) * 2 }, (_, k) => marquee[k % marquee.length]) : [];
    return `<div class="flex w-full flex-col"><div class="${CONTAINER} relative py-12 sm:py-20 md:py-28"><div class="relative flex min-w-0 max-w-3xl flex-col items-start">
      ${(p.badges || []).length ? `<div class="mb-5 flex flex-wrap gap-x-4 gap-y-2 sm:mb-6 sm:gap-x-5">${p.badges.map((b, i) => dotBadge(`${pad(i + 1)}. ${b.label}`)).join("")}</div>` : ""}
      <h1 class="text-foreground mb-5 max-w-full break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:mb-6 sm:text-5xl sm:leading-none md:text-7xl lg:text-8xl">${esc(p["main-heading"])}</h1>
      ${p["sub-heading"] ? `<p class="mb-8 max-w-xl text-base leading-normal text-foreground/80 sm:text-lg md:text-xl">${esc(p["sub-heading"])}</p>` : ""}
      ${ctas.length ? `<div class="flex flex-wrap items-center gap-x-6 gap-y-4">${ctas.map((c, i) => i === 0
        ? `<div>${button(c.label, c["data-prompt"], c.href)}</div>`
        : `<div><a href="#"${P(c["data-prompt"])}${H(c.href)} class="group inline-flex items-center gap-3 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground transition-colors hover:text-brand-cyan motion-safe:animate-bounce-y"><span class="grid h-9 w-9 place-items-center rounded-full border border-foreground/30">${I.down("tabler-icon h-4 w-4")}</span><span>${esc(c.label)}</span></a></div>`).join("")}</div>` : ""}
    </div></div>
    ${loop.length ? `<div class="relative w-full overflow-hidden border-y border-foreground/10 bg-foreground/5 py-4"><div class="wa-marquee flex w-max">${[0, 1].map(() => `<div class="flex shrink-0">${loop.map((m, i) => `<div class="flex shrink-0 items-center gap-6 pr-6 sm:gap-10 sm:pr-10"><span class="whitespace-nowrap font-inter text-2xl font-medium tracking-tighter sm:text-3xl md:text-5xl ${i % 2 ? "astro-text-outline" : "text-foreground"}">${esc(m)}</span><span class="text-base text-brand-cyan sm:text-xl md:text-2xl">✦</span></div>`).join("")}</div>`).join("")}</div></div>` : ""}
    </div>`;
  });

  /* ---------- 2. Services ---------- */
  def("astro-services-heading", (p) => `<div class="${CONTAINER} flex flex-col py-16">
    <div class="mb-8 flex flex-col items-start md:mb-10">${p["sur-heading"] ? `<span class="astro-st-code mb-2 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground">${esc(p["sur-heading"])}</span>` : ""}
      <h2 class="text-foreground max-w-full break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:text-6xl lg:text-7xl">${esc(p.heading)}</h2></div>
    <ol class="flex flex-col">${(p["list-items"] || []).map((x, i) => `<li class="flex flex-col gap-2 border-t border-foreground/10 px-1.5 py-5 transition-all duration-300 last:border-b hover:bg-gradient-to-r hover:from-brand-cyan/5 hover:via-transparent hover:to-transparent md:flex-row md:gap-6 md:py-7 md:hover:pl-3.5"><span class="shrink-0 font-plex-mono text-xs tracking-widest text-brand-cyan md:w-16 md:pt-2">${pad(i + 1)}</span><div class="flex min-w-0 flex-col"><h3 class="text-foreground mb-1.5 break-words font-inter text-2xl font-semibold tracking-tighter md:text-3xl">${esc(x.title)}</h3><p class="max-w-2xl text-sm text-foreground/70 sm:text-base">${esc(x["sub-title"])}</p></div></li>`).join("")}</ol></div>`);

  /* ---------- 3. Products ---------- */
  const CARD_BG = [tw`astro-card-2`, tw`astro-card-1`, tw`astro-card-3`, tw`astro-card-mesh`];
  def("astro-products-section", (p) => { const cards = p["product-cards"] || []; return `<div class="${CONTAINER} flex flex-col py-16">
    <div class="mb-8 flex flex-col gap-4 md:mb-10 md:flex-row md:items-end md:justify-between md:gap-8"><div class="flex min-w-0 flex-1 flex-col items-start">${p["sur-heading"] ? `<span class="mb-3 font-plex-mono text-xs font-medium uppercase tracking-widest text-brand-cyan md:mb-4">${esc(p["sur-heading"])}</span>` : ""}<h2 class="text-foreground max-w-3xl break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:text-6xl">${esc(p["main-heading"])}</h2></div><span class="astro-st-code shrink-0 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground md:mb-1.5"></span></div>
    <div class="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-5">${cards.map((c, i) => `<div class="flex ${i === cards.length - 1 && cards.length % 2 ? "md:col-span-2" : ""}"><article class="hover:astro-card-glow group relative flex min-h-80 w-full flex-col overflow-hidden rounded-3xl border border-foreground/10 bg-card p-6 text-foreground transition-all duration-300 ease-out hover:border-brand-cyan/40 md:min-h-96 md:p-7 ${CARD_BG[i % CARD_BG.length]}">
      <span class="pointer-events-none absolute inset-0 bg-gradient-to-br from-brand-cyan/15 via-transparent to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100"></span><span class="absolute right-5 top-4 font-plex-mono text-xs tracking-widest text-muted-foreground">${pad(i + 1, 3)}</span>
      <div class="relative mt-4 flex flex-wrap items-start justify-between gap-x-4 gap-y-2"><h3 class="text-foreground min-w-0 break-words font-inter text-3xl font-semibold tracking-tighter lg:text-4xl">${esc(c.title)}</h3>${c.badge ? `<span class="${STATUS}">${esc(c.badge)}</span>` : ""}</div>
      <p class="relative mb-5 mt-4 max-w-md text-sm text-foreground/70 sm:text-base">${esc(c["sub-title"])}</p>
      ${c.cta ? `<span class="relative inline-flex items-center gap-2 font-plex-mono text-xs uppercase tracking-widest text-brand-cyan mt-auto pt-8">${esc(c.cta)}${I.right("tabler-icon h-3.5 w-3.5 transition-transform duration-300 group-hover:translate-x-1")}</span>` : ""}</article></div>`).join("")}</div></div>`; });

  /* ---------- 4. Heading ---------- */
  def("astro-heading-section", (p) => `<div class="${CONTAINER} flex flex-col items-start py-16">${p["sur-heading"] ? `<span class="astro-st-code mb-3 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground md:mb-4">${esc(p["sur-heading"])}</span>` : ""}
    <h2 class="text-foreground mb-5 max-w-4xl break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:mb-6 md:text-6xl lg:text-7xl">${esc(p.heading)}</h2>${p["sub-text"] ? `<p class="${LEAD}">${esc(p["sub-text"])}</p>` : ""}</div>`);

  /* ---------- 5. CTA ---------- */
  def("astro-cta-section", (p) => { const w = words(p.heading); return `<div class="astro-void flex flex-col"><div class="${CONTAINER} flex flex-col items-start py-16">${p["sur-heading"] ? `<span class="astro-st-code mb-3 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground md:mb-4">${esc(p["sur-heading"])}</span>` : ""}
    <h2 class="text-foreground mb-4 max-w-5xl break-words font-inter text-5xl font-semibold leading-none tracking-tighter sm:text-6xl md:text-7xl lg:text-8xl"><span class="inline-block">${esc(w[0])}</span> <span class="text-brand-cyan">${esc(w.slice(1).join(" "))}</span></h2>
    ${p["sub-heading"] ? `<p class="${LEAD}">${esc(p["sub-heading"])}</p>` : ""}${(p.ctas || []).length ? `<div class="mt-8 flex flex-wrap gap-4">${p.ctas.map((c) => button(c.label, c["data-prompt"], c.href)).join("")}</div>` : ""}</div></div>`; });

  /* ---------- 6. Contact (form and company details are static on the live site) ---------- */
  const INPUT = tw`flex w-full border h-12 rounded-xl border-foreground/20 bg-foreground/5 px-4 py-3 text-base shadow-none transition-all duration-200 focus-visible:outline-none focus-visible:border-brand-cyan focus-visible:ring-4 focus-visible:ring-brand-cyan/10`;
  const field = (label, extra = "") => `<div class="space-y-2"><label class="text-sm font-medium text-foreground">${label}</label><input class="${INPUT}" data-local ${extra}></div>`;
  def("astro-contact-section", (p) => { const badges = (p.badges || []).length ? p.badges.map((b) => b.label) : ["Discovery call", "Eindhoven"]; return `<div class="${CONTAINER} flex flex-col py-16">
    <div class="mb-10 flex w-full min-w-0 max-w-4xl flex-col items-start md:mb-14"><div class="mb-5 flex flex-wrap gap-x-5 gap-y-2 sm:mb-6">${badges.map(dotBadge).join("")}</div>
      <h2 class="text-foreground mb-5 max-w-full break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:text-6xl lg:text-7xl">${esc(p.heading || "Tell us what you're building.")}</h2>
      <p class="${LEAD}">${esc(p["sub-heading"] || "We'll tell you honestly whether you need custom silicon at all, and what it would take to get there.")}</p></div>
    <div class="grid grid-cols-1 gap-10 lg:grid-cols-12 lg:gap-12"><div class="min-w-0 lg:col-span-7"><form onsubmit="return false" class="flex max-w-xl flex-col gap-4"><div class="grid grid-cols-1 gap-4 sm:grid-cols-2">${field("First name")}${field("Last name")}</div>${field("Work email", 'type="email"')}${field("Company")}
      <div class="space-y-2"><label class="text-sm font-medium text-foreground">What are you building?</label><textarea data-local rows="6" class="flex w-full border rounded-xl border-foreground/20 bg-foreground/5 px-4 py-3 text-base shadow-none transition-all duration-200 focus-visible:outline-none focus-visible:border-brand-cyan h-auto min-h-40 resize-y"></textarea></div>
      <button type="submit" data-action="Send message (form posts to Formspree)" class="${BTN} mt-2 self-start"><span>Send message</span>${I.right("tabler-icon h-4 w-4")}</button></form></div>
      <aside class="astro-void flex min-w-0 flex-col gap-8 self-start rounded-3xl border border-foreground/10 p-6 md:p-8 lg:col-span-5"><div class="flex flex-col"><h3 class="text-foreground mb-3 font-inter text-2xl font-semibold tracking-tighter md:text-3xl">Direct contact</h3><p class="text-sm leading-relaxed break-words text-foreground/70">Email: <a href="#" data-href="mailto:hello@korvanesilicon.eu" class="text-brand-cyan hover:underline">hello@korvanesilicon.eu</a></p></div>
        <div class="flex flex-col"><h3 class="text-foreground mb-3 font-inter text-2xl font-semibold tracking-tighter md:text-3xl">Company</h3><p class="text-sm leading-relaxed mb-1 text-foreground">Korvane Silicon B.V.</p><address class="not-italic text-muted-foreground">Kalkovenweg 117, 5652 RT Eindhoven, Netherlands</address>
          <ul class="mt-5 flex flex-wrap gap-x-5 gap-y-2"><li><a href="#" data-href="https://www.linkedin.com/company/korvane-silicon/" class="inline-flex min-h-6 items-center text-foreground transition-colors hover:text-brand-cyan">LinkedIn</a></li><li><a href="#" data-href="https://github.com/korvanesilicon" class="inline-flex min-h-6 items-center text-foreground transition-colors hover:text-brand-cyan">GitHub</a></li></ul></div></aside></div></div>`; });

  /* ---------- 7. Product ---------- */
  def("astro-product-section", (p) => { const L = p.lists || {}; const top = p["top-paragraph"] || {}; const bot = p["bottom-paragraph"] || {}; return `<article class="${CONTAINER} flex flex-col py-16">
    <div class="mb-10 flex"><div class="hover:astro-card-glow group relative flex min-h-60 w-full flex-col overflow-hidden rounded-3xl border border-foreground/10 bg-card p-6 text-foreground transition-all duration-300 ease-out hover:border-brand-cyan/40 sm:min-h-72 md:p-7 astro-card-mesh"><span class="pointer-events-none absolute inset-0 bg-gradient-to-br from-brand-cyan/15 via-transparent to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100"></span><span class="astro-st-code absolute right-5 top-4 font-plex-mono text-xs tracking-widest text-muted-foreground"></span>
      <div class="relative mt-6 flex flex-wrap items-start justify-between gap-x-4 gap-y-3"><div class="w-auto min-w-0 flex-1"><h2 class="text-foreground min-w-0 break-words font-inter text-4xl font-semibold leading-none tracking-tighter sm:text-5xl md:text-6xl lg:text-7xl">${esc(p["main-heading"])}</h2></div>${p.badge ? `<div class="w-auto shrink-0"><span class="${STATUS}">${esc(p.badge)}</span></div>` : ""}</div></div></div>
    <div class="flex min-w-0 flex-col items-start">
      ${top.title ? `<h3 class="${H3}">${esc(top.title)}</h3>` : ""}${top.text ? `<p class="${PARA}">${esc(top.text)}</p>` : ""}
      ${(L.numbered || []).length ? `<h3 class="${H3}">How it works</h3>${numbered(L.numbered)}` : ""}
      ${(L.bullet || []).length ? bullets(L.bullet) : ""}${labeled([...(L.labeled || []), ...(L.rich || [])])}
      ${bot.title ? `<h3 class="${H3}">${esc(bot.title)}</h3>` : ""}${bot.text ? `<p class="${PARA}">${esc(bot.text)}</p>` : ""}
      ${pills(p.pills)}${p.cta ? button(p.cta, `${p["main-heading"]}: ${p.cta}`, "", "mt-6") : ""}</div></article>`; });

  /* ---------- 8. List (card-items = grid of cards, list-items = text rows) ---------- */
  def("astro-list-section", (p) => {
    if ((p["card-items"] || []).length) return `<div class="${CONTAINER} flex flex-col py-12 sm:py-16 md:py-20">
      <div class="mb-8 flex flex-col items-start gap-3 md:mb-10 md:flex-row md:items-end md:justify-between md:gap-8"><div class="flex w-full min-w-0 max-w-full flex-1 flex-col"><h2 class="${H2}">${esc(p.heading)}</h2>${p["sub-heading"] ? `<p class="mt-4 ${LEAD}">${esc(p["sub-heading"])}</p>` : ""}</div><span class="astro-st-code shrink-0 font-plex-mono text-xs uppercase tracking-widest text-muted-foreground md:mb-2"></span></div>
      <ul class="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-5">${p["card-items"].map((x) => `<li class="min-w-0"><article class="flex h-full w-full flex-col rounded-3xl border border-foreground/10 bg-foreground/5 p-5 text-left transition-all duration-300 ease-out hover:-translate-y-1 hover:border-brand-cyan/30 sm:p-6"><h3 class="text-foreground mb-2 break-words font-inter text-xl font-semibold leading-tight tracking-tighter md:text-2xl">${esc(x.title)}</h3><p class="text-sm leading-relaxed break-words text-foreground/70">${esc(x["sub-title"])}</p></article></li>`).join("")}</ul></div>`;
    return `<div class="astro-void"><div class="${CONTAINER} flex flex-col py-16"><h2 class="${H2}">${esc(p.heading)}</h2>${p["sub-heading"] ? `<p class="mt-4 ${LEAD}">${esc(p["sub-heading"])}</p>` : ""}
      <ul class="mt-8 border-b border-foreground/10 md:mt-10">${(p["list-items"] || []).map((x) => `<li class="min-w-0"><div class="block w-full border-t border-foreground/10 py-4 text-left text-foreground/70 sm:py-5"><span class="block break-words"><span class="font-semibold text-foreground">${esc(x.title)}</span> ${esc(x["sub-title"])}</span></div></li>`).join("")}</ul></div></div>`;
  });

  /* ---------- 9. Content ---------- */
  def("astro-content-section", (p) => { const L = p.lists || {}; const sur = p["sur-heading"]; return `<article class="border-t border-foreground/10"><div class="${CONTAINER} flex min-w-0 flex-col items-start py-12 sm:py-16 md:py-24">
    <div class="mb-3 flex max-w-full flex-wrap items-center gap-x-3 gap-y-2 md:mb-4"><span class="astro-index-code break-words font-plex-mono text-xs uppercase tracking-widest text-brand-cyan">${esc(sur || "")}</span></div>
    <h2 class="text-foreground mb-5 max-w-4xl break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:mb-6 md:text-6xl">${esc(p["main-heading"])}</h2>
    ${p["sub-heading"] ? `<p class="mb-6 max-w-2xl break-words text-base leading-normal text-foreground/70 sm:text-lg md:mb-8 md:text-xl">${esc(p["sub-heading"])}</p>` : ""}
    ${(L.paragraph || []).map((x) => `${x.title ? `<h3 class="${H3}">${esc(x.title)}</h3>` : ""}<p class="${PARA}">${esc(x.text)}</p>`).join("")}
    ${(L.numbered || []).length ? numbered(L.numbered) : ""}${(L.bullet || []).length ? bullets(L.bullet) : ""}${labeled(L.rich || [])}
    ${pills(p.pills)}${p.cta ? button(p.cta, `${sur || p["main-heading"]}: ${p.cta}`, "", "mt-6") : ""}</div></article>`; });

  /* ---------- 10. FAQ ---------- */
  def("astro-faq-section", (p) => `<div class="astro-void"><div class="${CONTAINER} flex flex-col py-12 sm:py-16 md:py-20"><div class="flex flex-col"><h2 class="${H2}">${esc(p.heading)}</h2>${p["sub-heading"] ? `<p class="mt-4 ${LEAD}">${esc(p["sub-heading"])}</p>` : ""}</div>
    <div class="mt-8 flex max-w-3xl flex-col gap-3 md:mt-10">${(p.items || []).map((q, i) => `<div class="wa-acc overflow-hidden border rounded-2xl border-foreground/10" data-state="${i === 0 ? "open" : "closed"}"><h3 class="flex"><button type="button" data-local data-acc class="flex flex-1 items-center justify-between gap-3 bg-card text-left text-sm font-semibold transition-all px-4 py-4 sm:px-6 sm:py-5"><span class="break-words text-base font-semibold text-foreground sm:text-lg">${esc(q.question)}</span>${I.plus("wa-acc-icon tabler-icon size-4 shrink-0 text-muted-foreground transition-transform duration-200")}</button></h3>
      <div class="wa-acc-body overflow-hidden border-t border-border bg-background text-sm"><div class="leading-relaxed text-muted-foreground px-4 pb-5 pt-4 sm:px-6"><p class="text-sm leading-relaxed break-words text-foreground/70 sm:text-base">${esc(q.answer)}</p></div></div></div>`).join("")}</div></div></div>`,
    { script: "document.addEventListener('click',e=>{const b=e.target.closest('[data-acc]');if(!b)return;const a=b.closest('.wa-acc');a.dataset.state=a.dataset.state==='open'?'closed':'open'})" });

  /* ---------- 11. Team ---------- */
  const SOCIAL = tw`grid h-8 w-8 place-items-center rounded-full border border-foreground/20 text-muted-foreground transition-colors hover:border-brand-cyan hover:text-brand-cyan`;
  const socials = (s) => (s || []).length ? `<div class="mt-auto flex gap-2 pt-3">${s.map((x) => `<a href="#"${H(x.href || "#")} class="${SOCIAL}" aria-label="${esc(x.type)}">${(I[x.type] || I.linkedin)("tabler-icon h-4 w-4")}</a>`).join("")}</div>` : "";
  const ARTICLE = tw`group flex w-full overflow-hidden rounded-2xl border border-foreground/10 bg-card text-foreground transition-all duration-300 ease-out hover:astro-card-glow cursor-pointer hover:-translate-y-1 hover:border-brand-cyan/60`;
  const role = (m) => `<span class="break-words font-plex-mono text-xs font-medium uppercase tracking-widest text-brand-cyan">${esc(m.role)}</span>`;
  const photo = (m, cls, w, h, scrim) => `<div class="${cls}"><img class="object-cover absolute inset-0 h-full w-full grayscale-[.35] transition duration-500 group-hover:scale-105 group-hover:grayscale-0" alt="${esc(m.name)}" loading="lazy" src="${img(m.image, w, h)}">${scrim}</div>`;
  const tile = (m) => `<div class="flex w-72 shrink-0 snap-start sm:w-80 lg:w-96 first:ml-auto last:mr-auto"><article${P(m["data-prompt"])} class="${ARTICLE} flex-col">
    ${photo(m, tw`relative overflow-hidden bg-gradient-to-br from-brand-violet/30 to-brand-cyan/20 aspect-[4/5] w-full`, 480, 600, `<div class="pointer-events-none absolute from-transparent to-card inset-x-0 bottom-0 h-2/5 bg-gradient-to-b"></div>`)}
    <div class="flex min-w-0 flex-1 flex-col gap-1.5 px-5 pb-5 pt-1">${role(m)}<h3 class="text-foreground break-words font-inter font-semibold tracking-tight text-lg">${esc(m.name)}</h3><p class="mt-1 break-words text-sm leading-relaxed text-foreground/70">${esc(m.bio)}</p>${socials(m.socials)}</div></article></div>`;
  const lead = (m) => `<article${P(m["data-prompt"])} class="${ARTICLE} flex-col md:min-h-96 md:flex-row">
    ${photo(m, tw`relative overflow-hidden bg-gradient-to-br from-brand-violet/30 to-brand-cyan/20 aspect-[4/5] w-full md:aspect-auto md:w-5/12 md:shrink-0`, 720, 900, `<div class="pointer-events-none absolute from-transparent to-card inset-x-0 bottom-0 h-2/5 bg-gradient-to-b md:inset-y-0 md:left-auto md:h-full md:w-2/5 md:bg-gradient-to-r"></div>`)}
    <div class="flex min-w-0 flex-1 flex-col gap-1.5 justify-center px-5 pb-6 pt-1 md:px-8 md:py-8">${role(m)}<h3 class="text-foreground break-words font-inter font-semibold tracking-tight text-2xl md:text-3xl">${esc(m.name)}</h3><p class="mt-1 break-words text-sm leading-relaxed text-foreground/70 md:text-base">${esc(m.bio)}</p>${socials(m.socials)}</div></article>`;
  const row = (m) => `<div class="flex w-full flex-1"><article${P(m["data-prompt"])} class="${ARTICLE} flex-row">${photo(m, tw`relative overflow-hidden bg-gradient-to-br from-brand-violet/30 to-brand-cyan/20 h-auto min-h-32 w-24 shrink-0 sm:w-32`, 256, 320, "")}
    <div class="flex min-w-0 flex-1 flex-col gap-1.5 justify-center px-4 py-4 sm:px-5">${role(m)}<h3 class="text-foreground break-words font-inter font-semibold tracking-tight text-lg">${esc(m.name)}</h3><p class="mt-1 break-words text-sm leading-relaxed text-foreground/70">${esc(m.bio)}</p></div></article></div>`;
  def("astro-team-section", (p) => { const featured = p.variant === "featured"; const ms = p.members || []; return `<div class="${CONTAINER} flex flex-col py-12 sm:py-16 md:py-20">
    <div class="mb-8 flex flex-col md:mb-12 ${featured ? "items-start text-left" : "items-center text-center"}">${p["sur-heading"] ? `<span class="mb-3 font-plex-mono text-xs font-medium uppercase tracking-widest text-brand-cyan md:mb-4">${esc(p["sur-heading"])}</span>` : ""}<h2 class="text-foreground max-w-3xl break-words font-inter text-4xl font-semibold leading-tight tracking-tighter sm:text-5xl md:text-6xl">${esc(p.heading)}</h2>${p["sub-heading"] ? `<p class="mt-4 ${LEAD}">${esc(p["sub-heading"])}</p>` : ""}</div>
    ${featured
      ? `<div class="grid grid-cols-1 lg:grid-cols-12 gap-5"><div class="flex lg:col-span-7"><div class="flex w-full flex-1">${ms[0] ? lead(ms[0]) : ""}</div></div><div class="flex flex-col gap-5 lg:col-span-5">${ms.slice(1).map(row).join("")}</div></div>`
      : `<div class="no-scrollbar -mx-4 flex gap-5 overflow-x-auto px-4 py-2 sm:-mx-6 sm:px-6 md:-mx-12 md:px-12 snap-x snap-mandatory scroll-px-4 sm:scroll-px-6 md:scroll-px-12">${ms.map(tile).join("")}</div>`}
    ${(p.ctas || []).length ? `<div class="mt-10 flex md:mt-12 ${featured ? "justify-start" : "justify-center"}">${p.ctas.map((c) => button(c.label, c["data-prompt"], c.href)).join("")}</div>` : ""}</div>`; });
})();
